    public Object parseMarket(Object market)
    {
        Object baseId = this.safeString(market, "baseAssetName");
        Object quoteId = this.safeString(market, "quoteAssetName");
        Object id = this.safeString(market, "marketId");
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        Object fees = this.safeValue(this.safeDict(this.options, "fees", new java.util.HashMap<String, Object>() {{}}), quote, this.fees);
        Object pricePrecision = this.parseNumber(this.parsePrecision(this.safeString(market, "priceDecimals")));
        Object minAmount = this.safeNumber(market, "minOrderAmount");
        Object maxAmount = this.safeNumber(market, "maxOrderAmount");
        Object status = this.safeString(market, "status");
        Object minPrice = null;
        if (Helpers.isTrue(Helpers.isEqual(quote, "AUD")))
        {
            minPrice = pricePrecision;
        }
        final Object finalBase = base;
        final Object finalQuote = quote;
        final Object finalStatus = status;
        final Object finalMinPrice = minPrice;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "symbol", symbol );
            put( "base", finalBase );
            put( "quote", finalQuote );
            put( "settle", null );
            put( "baseId", baseId );
            put( "quoteId", quoteId );
            put( "settleId", null );
            put( "type", "spot" );
            put( "spot", true );
            put( "margin", false );
            put( "swap", false );
            put( "future", false );
            put( "option", false );
            put( "active", (Helpers.isEqual(finalStatus, "Online")) );
            put( "contract", false );
            put( "linear", null );
            put( "inverse", null );
            put( "taker", Helpers.GetValue(fees, "taker") );
            put( "maker", Helpers.GetValue(fees, "maker") );
            put( "contractSize", null );
            put( "expiry", null );
            put( "expiryDatetime", null );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", Btcmarkets.this.parseNumber(Btcmarkets.this.parsePrecision(Btcmarkets.this.safeString(market, "amountDecimals"))) );
                put( "price", pricePrecision );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", minAmount );
                    put( "max", maxAmount );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", finalMinPrice );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "created", null );
            put( "info", market );
        }});
    }

